// Connect to MongoDB and load the database into memory.
// Must be awaited once at server startup, before app.listen().
async function connectDB() {
  if (!MONGODB_URI) {
    throw new Error(
      "MONGODB_URI environment variable is not set. Add it in Render > Environment."
    );
  }

  mongoClient = new MongoClient(MONGODB_URI);
  await mongoClient.connect();
  const db = mongoClient.db(DB_NAME);
  mongoCollection = db.collection(COLLECTION_NAME);

  const existing = await mongoCollection.findOne({ _id: DOC_ID });

  if (existing) {
    delete existing._id;
    cachedData = existing;
    console.log("Design Makers database loaded from MongoDB.");
  } else {
    // SAFETY NET: previously, a missing document here silently triggered
    // creating a brand-new database from `defaultDatabase` (the hardcoded
    // sample products). That's exactly what happens if MONGODB_URI ever
    // points somewhere new/wrong (bad env var, wrong cluster) after the
    // site has been live for a while — the app would quietly "reset" to
    // only the code's sample data, making it look like every admin-added
    // product vanished, even though the real data was untouched and just
    // sitting in the old database, now orphaned.
    //
    // Now this fails loudly instead of failing silently: unless someone
    // explicitly confirms this is a brand-new site (ALLOW_NEW_DATABASE=true),
    // the server refuses to start and logs exactly why. A misconfigured
    // MONGODB_URI now means visible downtime you'll notice immediately,
    // instead of invisible data loss you might not notice for days.
    if (process.env.ALLOW_NEW_DATABASE !== "true") {
      throw new Error(
        `No existing database document found (_id="${DOC_ID}" in ${DB_NAME}.${COLLECTION_NAME}). ` +
          `If this is genuinely a brand-new site, set ALLOW_NEW_DATABASE=true in your environment once ` +
          `and redeploy to initialize it. If this site was already live, DO NOT set that — your MONGODB_URI ` +
          `is most likely pointing at the wrong cluster/database right now. Check it in your hosting ` +
          `environment variables and fix it before restarting; your real data is very likely still intact ` +
          `in the correct database, just not the one this URI currently points to.`,
      );
    }
    cachedData = JSON.parse(JSON.stringify(defaultDatabase));
    await mongoCollection.insertOne({ _id: DOC_ID, ...cachedData });
    console.log("Design Makers database created in MongoDB (first run, ALLOW_NEW_DATABASE=true).");
  }

  ensureShape(cachedData);
}

// Self-heal: older databases won't have these fields yet.
function ensureShape(database) {
  let needsUpgrade = false;

  if (!Array.isArray(database.customers)) {
    database.customers = [];
    needsUpgrade = true;
  }
  // Older customer records (or ones created before Google login existed)
  // won't have the seller/role fields yet — backfill sane defaults.
  database.customers.forEach((c) => {
    if (!c.role) {
      c.role = "customer";
      needsUpgrade = true;
    }
    if (!c.sellerStatus) {
      c.sellerStatus = "none";
      needsUpgrade = true;
    }
    if (typeof c.shopTitle !== "string") {
      c.shopTitle = "";
      needsUpgrade = true;
    }
  });

  if (!Array.isArray(database.reviews)) {
    database.reviews = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.sellerApplications)) {
    database.sellerApplications = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.sellers)) {
    database.sellers = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.sellerPasswordResetRequests)) {
    database.sellerPasswordResetRequests = [];
    needsUpgrade = true;
  }

  if (!database.settings) {
    database.settings = {};
    needsUpgrade = true;
  }

  if (!database.settings.rewards) {
    database.settings.rewards = {
      enabled: false,
      earnPerRupee: 0.01,
      redeemRate: 0.1,
      minRedeemPoints: 500,
      maxRedeemPerOrder: 500,
      pointsPerHundredSpent: 1,
      redeemPoints: 500,
      redeemValue: 50,
    };
    needsUpgrade = true;
  } else if (database.settings.rewards.maxRedeemPerOrder == null) {
    database.settings.rewards.maxRedeemPerOrder = database.settings.rewards.minRedeemPoints || 0;
    needsUpgrade = true;
  }

  if (!database.settings.saleBanner) {
    database.settings.saleBanner = { enabled: false, text: "" };
    needsUpgrade = true;
  }

  const VALID_THEMES = ["normal", "rakshabandhan", "aug15"];
  if (!VALID_THEMES.includes(database.settings.theme)) {
    database.settings.theme = "normal";
    needsUpgrade = true;
  }

  if (!Array.isArray(database.admins)) {
    database.admins = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.loginHistory)) {
    database.loginHistory = [];
    needsUpgrade = true;
  }

  if (!Array.isArray(database.productViews)) {
    database.productViews = [];
    needsUpgrade = true;
  }

  return needsUpgrade;
}

// Read database (synchronous — served from the in-memory cache that
// connectDB() populated at startup).
function readDatabase() {
  if (!cachedData) {
    throw new Error("Database not initialized yet. Call connectDB() before handling requests.");
  }
  if (ensureShape(cachedData)) {
    writeDatabase(cachedData);
  }
  return cachedData;
}

// Save database — updates the in-memory cache immediately (so the next
// readDatabase() sees the change right away) and persists to MongoDB
// in the background.
function writeDatabase(data) {
  cachedData = data;

  if (mongoCollection) {
    mongoCollection
      .replaceOne({ _id: DOC_ID }, { _id: DOC_ID, ...data }, { upsert: true })
      .catch((err) => {
        console.error("Failed to persist database to MongoDB:", err.message);
      });
  }

  return data;
}

// Generate next ID
function getNextId(items) {
  if (!items.length) {
    return 1;
  }
  return Math.max(...items.map((item) => item.id)) + 1;
}

module.exports = {
  connectDB,
  readDatabase,
  writeDatabase,
  getNextId,
};
